WITH filtered AS (SELECT id, session_id, event_type, event_time, duration_sec, CASE WHEN event_type IN ('purchase', 'click') THEN 'Group A' ELSE 'Other' END AS event_type_group, CASE WHEN duration_sec >= 425 THEN 'High' WHEN duration_sec >= 163 THEN 'Medium' ELSE 'Low' END AS duration_sec_band FROM web_events WHERE duration_sec > 301) SELECT DATE_TRUNC('WEEK', event_time) AS week_start, CASE WHEN duration_sec >= 466 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_tier, STDDEV_SAMP(duration_sec) AS duration_sec_stddev, MAX(event_time) AS last_seen, COUNT(*) FILTER (WHERE event_type = 'search') AS search_rows, COUNT(DISTINCT session_id) AS distinct_session_ids, APPROX_PERCENTILE(duration_sec, ARRAY(0.25, 0.5, 0.75)) AS duration_sec_quartiles FROM filtered GROUP BY DATE_TRUNC('WEEK', event_time), CASE WHEN duration_sec >= 466 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING COUNT(DISTINCT session_id) > 1
